/**
 * M2 parity check — lib/m2/signal.ts must reproduce strategies/m2/m2_alert.py EXACTLY.
 *
 *   npm run selftest:m2
 *
 * The fixture is generated by the Python (`python strategies/m2/m2_alert.py --emit-fixture`)
 * and the Python's own --selftest fails if the committed fixture is stale, so this check
 * always compares against the CURRENT alert logic. Every comparison is exact (===),
 * including the SMA doubles: the page and the Telegram alert must never disagree on the
 * filter, the streak, the strike or the state transition.
 */
import fixture from "../strategies/m2/parity_fixture.json";
import {
  QUOTE_TS_FIELDS,
  SMA_EXIT,
  SMA_FILTER,
  MAX_HOLD,
  STRIKE_MULT,
  STALE_MINUTES,
  etNowIso,
  evaluate,
  isSession,
  lowerCloseStreak,
  quoteFromRow,
  type Bar,
  type M2State,
} from "../lib/m2/signal";

let passed = 0;
let failed = 0;
function check(label: string, actual: unknown, expected: unknown): void {
  const a = JSON.stringify(actual);
  const e = JSON.stringify(expected);
  if (a === e) {
    passed++;
  } else {
    failed++;
    console.log(`  FAIL ${label}\n       expected ${e}\n       actual   ${a}`);
  }
}

console.log("[1] constants");
const c = fixture.constants;
check("sma_filter", SMA_FILTER, c.sma_filter);
check("sma_exit", SMA_EXIT, c.sma_exit);
check("max_hold", MAX_HOLD, c.max_hold);
check("strike_mult", STRIKE_MULT, c.strike_mult);
check("stale_minutes", STALE_MINUTES, c.stale_minutes);
check("quote_ts_fields order", [...QUOTE_TS_FIELDS], c.quote_ts_fields);

console.log("[2] streak");
for (const s of fixture.streak)
  check(`streak ${JSON.stringify(s.closes)}`, lowerCloseStreak(s.closes), s.expected);

console.log("[3] Eastern time (DST edges)");
for (const t of fixture.et_now) check(`et ${t.utc}`, etNowIso(new Date(`${t.utc}Z`)), t.expected);

console.log("[4] NYSE sessions (shared calendar)");
for (const s of fixture.is_session) check(`session ${s.date}`, isSession(s.date), s.expected);

console.log("[5] IEX quote parsing");
for (const q of fixture.quotes) {
  const r = quoteFromRow(q.row as Record<string, unknown>);
  check(`quote ${JSON.stringify(q.row).slice(0, 60)}`, { px: r.px, et: r.etIso }, q.expected);
}

console.log("[6] evaluate");
for (const k of fixture.evaluate) {
  const r = evaluate(k.history as Bar[], k.px, k.today, k.state as unknown as M2State, k.friday);
  const e = k.expected;
  check(`${k.name}: kinds`, r.kinds, e.kinds);
  check(`${k.name}: sma200 (exact double)`, r.sma200, e.sma200);
  check(`${k.name}: sma5 (exact double)`, r.sma5, e.sma5);
  check(`${k.name}: streak`, r.streak, e.streak);
  check(`${k.name}: filter`, r.filterOn, e.filter_on);
  check(`${k.name}: strike (half-even)`, r.strike, e.strike);
  check(
    `${k.name}: state`,
    {
      in_trade: r.state.in_trade,
      entry_date: r.state.entry_date,
      strike: r.state.strike,
      hold_day: r.state.hold_day,
      last_entry_streak_id: r.state.last_entry_streak_id,
    },
    e.state
  );
  check(`${k.name}: ledger`, r.ledger, e.ledger);
}

console.log(`\n${failed === 0 ? "ALL PASS" : "FAILURES"} — ${passed} passed, ${failed} failed`);
process.exit(failed === 0 ? 0 : 1);
